   527	export const proposeSyncTask = async ({
   528	  worker,
   529	  syncFunction,
   530	  supabaseClient,
   531	  context,
   532	}: {
   533	  worker: string;
   534	  syncFunction: string;
   535	  supabaseClient: DGSupabaseClient;
   536	  context: SupabaseContext;
   537	}): Promise<SyncTaskInfo> => {
   538	  try {
   539	    const now = new Date();
   540	    const { data, error } = await supabaseClient.rpc("propose_sync_task", {
   541	      s_target: context.spaceId,
   542	      s_function: syncFunction,
   543	      s_worker: worker,
   544	      task_interval: SYNC_INTERVAL,
   545	      timeout: SYNC_TIMEOUT,
   546	    });
   547	
   548	    if (error) {
   549	      console.error(
   550	        `proposeSyncTask: propose_sync_task failed - ${error.message}`,
   551	      );
   552	      return {
   553	        shouldProceed: false,
   554	        failure: {
   555	          cause: error,
   556	          context: getSupabaseErrorTelemetry({
   557	            error,
   558	            prefix: "proposeSyncError",
   559	          }),
   560	        },
   561	      };
   562	    }
   563	
   564	    if (typeof data === "string") {
   565	      const timestamp = new Date(data);
   566	
   567	      if (timestamp > now) {
   568	        return {
   569	          nextUpdateTime: timestamp,
   570	          shouldProceed: false,
   571	        };
   572	      } else {
   573	        return {
   574	          lastUpdateTime: timestamp,
   575	          shouldProceed: true,
   576	        };
   577	      }
   578	    }
   579	
   580	    return { shouldProceed: true };
   581	  } catch (error) {
   582	    console.error(
   583	      `proposeSyncTask: Unexpected error while contacting sync-task API:`,
   584	      error,
   585	    );
   586	    return {
   587	      shouldProceed: false,
   588	      failure: {
   589	        cause: error,
   590	        context:
   591	          typeof error === "object" && error !== null
   592	            ? getSupabaseErrorTelemetry({
   593	                error,
   594	                prefix: "proposeSyncError",
   595	              })
   596	            : undefined,
   597	      },
   598	    };
   599	  }
   600	};
