355	export const endSyncTask = async ({
356	  worker,
357	  syncFunction,
358	  status,
359	  showToast = false,
360	  taskStartedAt,
361	  context,
362	  supabaseClient,
363	  telemetryContext,
364	}: {
365	  worker: string;
366	  syncFunction: string;
367	  status: Enums<"task_status">;
368	  showToast: boolean;
369	  taskStartedAt: Date;
370	  context?: SupabaseContext;
371	  supabaseClient?: DGSupabaseClient;
372	  telemetryContext?: Properties;
373	}): Promise<EndSyncTaskResult> => {
374	  const getEndTelemetryContext = (
375	    resolvedContext?: SupabaseContext,
376	  ): Properties => ({
377	    syncWorkerId: worker,
378	    syncFunction,
379	    spaceId: resolvedContext?.spaceId ?? context?.spaceId,
380	    ...(telemetryContext || {}),
381	  });
382	
383	  try {
384	    const resolvedClient = supabaseClient || (await getLoggedInClient());
385	    if (!resolvedClient) {
386	      const error = new Error("Missing Supabase client while ending sync task");
387	      return notifyEndSyncFailure({
388	        error,
389	        status,
390	        showToast: false,
391	        reason: error.message,
392	        context: getEndTelemetryContext(),
393	      });
394	    }
395	    const resolvedContext = context || (await getSupabaseContext());
396	    if (!resolvedContext) {
397	      console.error("endSyncTask: Unable to obtain Supabase context.");
398	      const error = new Error("Unable to obtain Supabase context");
399	      return notifyEndSyncFailure({
400	        error,
401	        status,
402	        showToast: false,
403	        reason: error.message,
404	        context: getEndTelemetryContext(),
405	      });
406	    }
407	    const { data, error } = await resolvedClient.rpc("end_sync_task", {
408	      s_target: resolvedContext.spaceId,
409	      s_function: syncFunction,
410	      s_worker: worker,
411	      s_status: status,
412	      s_started_at: taskStartedAt.toISOString(),
413	    });
414	    if (error) {
415	      console.error("endSyncTask: Error calling end_sync_task:", error);
416	      const reason = `Supabase end_sync_task RPC failed: ${error.message ?? "Unknown error"}`;
417	      const capturedError = new Error(reason, { cause: error });
418	      return notifyEndSyncFailure({
419	        error: capturedError,
420	        status,
421	        showToast,
422	        reason,
423	        context: {
424	          ...getEndTelemetryContext(resolvedContext),
425	          ...getSupabaseErrorTelemetry({ error, prefix: "endSyncError" }),
426	        },
427	      });
428	    }
429	
430	    if (!isEndSyncTaskRpcResult(data)) {
431	      const resultVersion = getEndSyncTaskResultVersion(data);
432	      if (resultVersion > END_SYNC_TASK_RESULT_VERSION) {
433	        const rpcResult: EndSyncTaskRpcResult = {
434	          version: resultVersion,
435	          ok: true,
436	          stale: false,
437	          reason: "unsupported_future_result_version",
438	        };
439	        posthog.capture("Sync end task future result", {
440	          ...telemetryContext,
441	          endSyncPayload: data,
442	          endSyncResult: rpcResult,
443	        });
444	
445	        return {
446	          ok: true,
447	          stale: false,
448	          rpcResult,
449	        };
450	      }
451	
452	      const reason = "Supabase end_sync_task returned unexpected payload";
453	      const capturedError = new Error(reason);
454	      return notifyEndSyncFailure({
455	        error: capturedError,
456	        status,
457	        showToast,
458	        reason,
459	        context: {
460	          ...getEndTelemetryContext(resolvedContext),
461	          endSyncPayload: data,
462	        },
463	      });
464	    }
465	
466	    const rpcResult = data;
467	    if (rpcResult?.stale === true) {
468	      posthog.capture("Sync end task stale", {
469	        ...telemetryContext,
470	        endSyncResult: rpcResult,
471	      });
472	
473	      return {
474	        ok: false,
475	        stale: true,
476	        rpcResult,
477	      };
478	    }
479	
480	    if (rpcResult?.ok === false) {
481	      const reason =
482	        rpcResult.reason || "Supabase end_sync_task returned failure";
483	      const capturedError = new Error(reason);
484	      return notifyEndSyncFailure({
485	        error: capturedError,
486	        status,
487	        showToast,
488	        reason,
489	        context: {
490	          ...getEndTelemetryContext(resolvedContext),
491	          endSyncResult: rpcResult,
492	        },
493	        rpcResult,
494	      });
495	    }
496	
497	    if (showToast) {
498	      if (status === "failed") {
499	        renderToast({
500	          id: "discourse-embedding-failed",
501	          content: "Discourse node embeddings sync failed",
502	          intent: "danger",
503	          timeout: 5000,
504	        });
505	      }
506	    }
507	
508	    return { ok: true, stale: false, rpcResult };
509	  } catch (error) {
510	    console.error("endSyncTask: Error calling end_sync_task:", error);
511	    const reason =
512	      error instanceof Error
513	        ? `Unexpected error ending sync task: ${error.message}`
514	        : "Unexpected non-error thrown while ending sync task";
515	    const capturedError =
516	      error instanceof Error ? error : new Error(reason, { cause: error });
517	    return notifyEndSyncFailure({
518	      error: capturedError,
519	      status,
520	      showToast,
521	      reason,
522	      context: getEndTelemetryContext(),
523	    });
524	  }
525	};
