650	export const convertDgToSupabaseConcepts = async ({
651	  nodesSince,
652	  since,
653	  allNodeTypes,
654	  sharedNodeTypeIds = new Set<string>(),
655	  backfillNodeTypeIds = new Set<string>(),
656	  supabaseClient,
657	  context,
658	}: {
659	  nodesSince: RoamDiscourseNodeData[];
660	  since: number | undefined;
661	  allNodeTypes: DiscourseNode[];
662	  sharedNodeTypeIds?: ReadonlySet<string>;
663	  backfillNodeTypeIds?: ReadonlySet<string>;
664	  supabaseClient: DGSupabaseClient;
665	  context: SupabaseContext;
666	}) => {
667	  const changedNodeTypes = await nodeTypeSince(since, allNodeTypes);
668	  const nodeTypesByUid = new Map(
669	    changedNodeTypes.map((nodeType) => [nodeType.type, nodeType]),
670	  );
671	
672	  allNodeTypes.forEach((nodeType) => {
673	    if (
674	      sharedNodeTypeIds.has(nodeType.type) ||
675	      backfillNodeTypeIds.has(nodeType.type)
676	    ) {
677	      nodeTypesByUid.set(nodeType.type, nodeType);
678	    }
679	  });
680	  const nodeTypes = Array.from(nodeTypesByUid.values());
681	
682	  await upsertNodeSchemaToContent({
683	    nodeTypesUids: nodeTypes.map((node) => node.type),
684	    spaceId: context.spaceId,
685	    userId: context.userId,
686	    supabaseClient,
687	  });
688	
689	  const nodesTypesToLocalConcepts = nodeTypes.map((node) => {
690	    return discourseNodeSchemaToLocalConcept(context, node);
691	  });
692	
693	  const schemasByUid = new Map(
694	    allNodeTypes.map((nodeType) => [nodeType.type, nodeType]),
695	  );
696	
697	  const nodeBlockToLocalConcepts = nodesSince.map((node) => {
698	    const localConcept = discourseNodeBlockToLocalConcept(context, {
699	      nodeUid: node.source_local_id,
700	      schemaUid: node.type,
701	      title: node.node_title ?? node.text,
702	      schema: schemasByUid.get(node.type),
703	    });
704	    return localConcept;
705	  });
706	
707	  const conceptsToUpsert = [
708	    ...nodesTypesToLocalConcepts,
709	    ...nodeBlockToLocalConcepts,
710	  ];
711	  const { ordered, missing } = orderConceptsByDependency(conceptsToUpsert);
712	
713	  if (missing.length > 0) {
714	    console.warn(
715	      "Some concept dependencies were not in the current sync batch:",
716	      missing,
717	    );
718	  }
719	
720	  await upsertConceptBatches({
721	    concepts: ordered,
722	    supabaseClient,
723	    spaceId: context.spaceId,
724	  });
725	};
