955	    copied,
956	    unchanged,
957	    distinctBlobs,
958	    tooLarge: tooLarge.length,
959	    failed: failed.length,
960	  });
961	  // Per node, unlike the summary: the same file failing in two nodes is two retries.
962	  for (const result of results) {
963	    if (result.status !== "failed") continue;
964	    posthog.capture("Sync shared node asset failed", {
965	      sourceLocalId: result.sourceLocalId,
966	      sourceRef: withoutUrlQueries(result.sourceRef),
967	      error: withoutUrlQueries(result.error),
968	      retryScheduled: retried.has(result.sourceLocalId),
969	    });
