      [?page_id :block/uid ?page_uid]
  ]`,
    node_uid,
  );
  if (result.length !== 1 || result[0].length !== 4)
    throw new Error("Invalid result from Roam query");

  const [author_uid, page_uid, created_t, last_modified_t] = result[0] as [
    string,
    string,
    number,
    number,
  ];
  const created = new Date(created_t).toISOString();
  const last_modified = new Date(last_modified_t).toISOString();
  return {
    author_local_id: author_uid,
    created,
    last_modified,
    page_uid,
  };
  /* eslint-enable @typescript-eslint/naming-convention */
};

export const discourseNodeSchemaToLocalConcept = (
  context: SupabaseContext,
  node: DiscourseNode,
): LocalConceptDataInput => {
  const literalContent: Record<string, Json> = {
    label: node.text,
    format: node.format,
  };
  const templateContent = nodeTemplateContent(node.template);
  if (templateContent !== undefined)
    literalContent.template_content = templateContent;
  const hasSourceSlot = schemaHasSourceSlot(node);
  if (hasSourceSlot) literalContent.roles = [SOURCE_SLOT];
  return {
    space_id: context.spaceId,
    name: node.text,
    source_local_id: node.type,
    is_schema: true,
    literal_content: literalContent,
    ...(hasSourceSlot
      ? { local_reference_content: { [SOURCE_SLOT]: sourceSlotSchemaId() } }
      : {}),
    /* eslint-enable @typescript-eslint/naming-convention */
    ...getNodeExtraData(node.type),
  };
};

